","known_bad_label":"Creates one shared delivery object per publication instead of an independent message copy for each listener."},{"id":"cap-v2-graph_and_tree-typescript-generation-01","problem":"Write one complete TypeScript source file implementing the following exact API:

```ts
export interface ParentLink {
  readonly id: string;
  readonly parentId: string | null;
}

export interface TreeReport {
  readonly rootId: string;
  readonly preorder: readonly string[];
  readonly depthById: Readonly<Record<string, number>>;
  readonly pathById: Readonly<Record<string, readonly string[]>>;
}

export function inspectParentTree(
  links: readonly ParentLink[],
): TreeReport;
```

The input describes a rooted tree. Validate its structure before producing the report:

- Repeated IDs must throw `new RangeError("Duplicate node: " + id)`.
- The input must contain exactly one link whose `parentId` is `null`; otherwise throw `new RangeError("Expected exactly one root")`.
- A non-null parent absent from the input must throw `new RangeError("Unknown parent: " + parentId)`.
- Any parent cycle must throw `new RangeError("Cycle detected")`.

For valid input, children of each node follow their order in `links`. Traverse from the root in preorder. `depthById` maps the root to `0` and every other node to its edge distance from the root. `pathById[id]` is the ordered ID path from the root through `id`, inclusive.

The implementation must be self-contained and deterministic. Do not use filesystem, network, clock, randomness, external packages, or frameworks. It must compile under strict TypeScript as CommonJS targeting ES2022.","reference_code":"export interface ParentLink {
  readonly id: string;
  readonly parentId: string | null;
}

export interface TreeReport {
  readonly rootId: string;
  readonly preorder: readonly string[];
  readonly depthById: Readonly<Record<string, number>>;
  readonly pathById: Readonly<Record<string, readonly string[]>>;
}

export function inspectParentTree(
  links: readonly ParentLink[],
): TreeReport {
  const byId = new Map<string, ParentLink>();
  const children = new Map<string, string[]>();

  for (const link of links) {
    if (byId.has(link.id)) {
      throw new RangeError("Duplicate node: " + link.id);
    }
    byId.set(link.id, link);
    children.set(link.id, []);
  }

  const roots = links.filter((link) => link.parentId === null);
  if (roots.length !== 1) {
    throw new RangeError("Expected exactly one root");
  }

  for (const link of links) {
    if (link.parentId === null) continue;
    if (!byId.has(link.parentId)) {
      throw new RangeError("Unknown parent: " + link.parentId);
    }
    children.get(link.parentId)!.push(link.id);
  }

  const state = new Map<string, 0 | 1 | 2>();
  const visitParent = (id: string): void => {
    const current = state.get(id) ?? 0;
    if (current === 1) throw new RangeError("Cycle detected");
    if (current === 2) return;
    state.set(id, 1);
    const parentId = byId.get(id)!.parentId;
    if (parentId !== null && byId.has(parentId)) visitParent(parentId);
    state.set(id, 2);
  };

  for (const link of links) visitParent(link.id);

  const rootId = roots[0].id;
  const preorder: string[] = [];
  const depthById = Object.create(null) as Record<string, number>;
  const pathById = Object.create(null) as Record<string, readonly string[]>;

  const walk = (id: string, depth: number, path: readonly string[]): void => {
    const nextPath = [...path, id];
    preorder.push(id);
    depthById[id] = depth;
    pathById[id] = nextPath;
    for (const childId of children.get(id)!) {
      walk(childId, depth + 1, nextPath);
    }
  };

  walk(rootId, 0, []);
  return { rootId, preorder, depthById, pathById };
}
