  for (const row of rows) {
    if (!Number.isInteger(row.depth) || row.depth < 0) {
      throw new RangeError("Invalid depth at: " + row.id);
    }

    const effectiveDepth = Math.min(row.depth, stack.length);
    while (stack.length > effectiveDepth) stack.pop();
    const parent = effectiveDepth === 0 ? undefined : stack[effectiveDepth - 1];
