    if (parent === undefined) roots.push(node);
    else parent.children.push(node);

    stack[effectiveDepth] = node;
    stack.length = effectiveDepth + 1;
  }

  const measure = (node: OutlineNode): number => {
    let size = 1;
    for (const child of node.children) size += measure(child);
    node.subtreeSize = size;
    return size;
  };

  for (const root of roots) measure(root);
  return roots;
}
","known_bad_label":"Clamps malformed upward depth jumps to the deepest available level instead of rejecting them."},{"id":"cap-v2-graph_and_tree-typescript-repair-01","problem":"Repair the implementation below and return one complete TypeScript source file.

Export exactly this API:

```ts
export interface BuildTask {
  readonly id: string;
  readonly dependsOn: readonly string[];
}

export function stableBuildOrder(
  tasks: readonly BuildTask[],
): readonly string[];
```

The input is guaranteed to describe a directed acyclic dependency graph with unique task IDs, existing dependency IDs, and no repeated dependency within a task.

Return a topological ordering. At each selection step, if multiple unprocessed tasks currently have no remaining dependencies, select the one occurring earliest in the original `tasks` array. A task becoming eligible does not jump ahead of an already eligible task that appeared earlier in the input. The function must not mutate `tasks` or any `dependsOn` array.

The implementation must be self-contained and deterministic. Do not use filesystem, network, clock, randomness, external packages, or frameworks. It must compile under strict TypeScript as CommonJS targeting ES2022.

The current source incorrectly uses task IDs as its tie-breaker:

```ts
export interface BuildTask {
  readonly id: string;
  readonly dependsOn: readonly string[];
}

export function stableBuildOrder(
  tasks: readonly BuildTask[],
): readonly string[] {
  const remaining = new Map<string, number>();
  const dependents = new Map<string, string[]>();

  for (const task of tasks) {
    remaining.set(task.id, task.dependsOn.length);
    dependents.set(task.id, []);
  }
  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      dependents.get(dependency)!.push(task.id);
    }
  }

  const ready = tasks
    .filter((task) => task.dependsOn.length === 0)
    .map((task) => task.id);
  const order: string[] = [];

  while (ready.length > 0) {
    ready.sort((left, right) =>
      left < right ? -1 : left > right ? 1 : 0,
    );
    const current = ready.shift()!;
    order.push(current);

    for (const dependent of dependents.get(current)!) {
      const count = remaining.get(dependent)! - 1;
      remaining.set(dependent, count);
      if (count === 0) ready.push(dependent);
    }
  }

  return order;
}
