{"items":[{"id":"cap-v2-callbacks_and_events-typescript-repair-01","test_code":"import { runMutationListeners } from "./solution";
import type { MutationListener } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equalArray(actual: readonly string[], expected: readonly string[], message: string): void {
  assert(actual.length === expected.length, message + " (length)");
  for (let i = 0; i < expected.length; i++) {
    assert(actual[i] === expected[i], message + " (index " + i + ")");
  }
}

{
  const source = Object.freeze(["original", "value"]);
  const calls: string[] = [];
  let completeCalls = 0;
  let resultError: Error | null | undefined;
  let resultSnapshots: readonly (readonly string[])[] | undefined;

  const listeners: MutationListener[] = [
    (items, done) => {
      calls.push("first");
      equalArray(items, ["original", "value"], "first listener input");
      items[0] = "first-mutated";
      items.push("first-added");
      done();
      done(new Error("ignored repeat"));
      throw new Error("ignored after acknowledgement");
    },
    (items, done) => {
      calls.push("second");
      equalArray(items, ["original", "value"], "second listener must get pristine copy");
      items.splice(1, 1, "second-mutated");
      done();
    },
  ];

  runMutationListeners(source, listeners, (error, snapshots) => {
    completeCalls++;
    resultError = error;
    resultSnapshots = snapshots;
  });

  assert(completeCalls === 1, "successful pipeline must complete once");
  assert(resultError === null, "successful pipeline must report null");
  assert(resultSnapshots !== undefined, "successful pipeline must return snapshots");
  assert(resultSnapshots.length === 2, "must save one snapshot per listener");
  equalArray(resultSnapshots[0], ["first-mutated", "value", "first-added"], "first snapshot");
  equalArray(resultSnapshots[1], ["original", "second-mutated"], "second snapshot");
  assert(Object.isFrozen(resultSnapshots[0]), "first snapshot must be immutable");
  assert(Object.isFrozen(resultSnapshots[1]), "second snapshot must be immutable");
  equalArray(source, ["original", "value"], "source must not be mutated");
  equalArray(calls, ["first", "second"], "listeners must run in order");
}

{
  const events: string[] = [];
  let firstDone: ((error?: Error) => void) | undefined;
  let secondDone: ((error?: Error) => void) | undefined;
  let completed = false;

  runMutationListeners(
    ["x"],
    [
      (_items, done) => {
        events.push("first-start");
        firstDone = done;
      },
      (_items, done) => {
        events.push("second-start");
        secondDone = done;
      },
    ],
    () => {
      completed = true;
      events.push("complete");
    },
  );

  equalArray(events, ["first-start"], "second listener must wait for first acknowledgement");
  assert(firstDone !== undefined, "first callback must be captured");
  firstDone();
  equalArray(events, ["first-start", "second-start"], "second listener should start after success");
  assert(!completed, "pipeline must wait for second listener");
  assert(secondDone !== undefined, "second callback must be captured");
  secondDone();
  equalArray(events, ["first-start", "second-start", "complete"], "completion order");
}

{
  const failure = new Error("listener failed");
  let laterCalled = false;
  let completeCalls = 0;
  let receivedError: Error | null | undefined;
  let snapshotCount = -1;

  runMutationListeners(
    ["base"],
    [
      (items, done) => {
        items.push("saved");
        done();
      },
      (_items, done) => {
        done(failure);
        done();
        throw new Error("later throw must be ignored");
      },
      (_items, done) => {
        laterCalled = true;
        done();
      },
    ],
    (error, snapshots) => {
      completeCalls++;
      receivedError = error;
      snapshotCount = snapshots.length;
    },
  );

  assert(receivedError === failure, "callback error identity must be preserved");
  assert(snapshotCount === 1, "failure must exclude failing listener snapshot");
  assert(!laterCalled, "listeners after a failure must not run");
  assert(completeCalls === 1, "failed pipeline must complete once");
}

{
  let received: Error | null | undefined;
  runMutationListeners(
    [],
    [() => {
      throw "plain failure";
    }],
    (error, snapshots) => {
      received = error;
      assert(snapshots.length === 0, "throwing listener must not create a snapshot");
    },
  );
  assert(received instanceof Error, "non-Error throw must be converted");
  assert(received.message === "plain failure", "converted throw message");
}

{
  let calls = 0;
  runMutationListeners([], [], (error, snapshots) => {
    calls++;
    assert(error === null, "empty pipeline must succeed");
    assert(snapshots.length === 0, "empty pipeline must have no snapshots");
  });
  assert(calls === 1, "empty pipeline must complete immediately once");
}
