import type { Broadcast } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equalStrings(actual: readonly string[], expected: readonly string[], message: string): void {
  assert(actual.length === expected.length, message + " (length)");
  for (let i = 0; i < expected.length; i++) {
    assert(actual[i] === expected[i], message + " (index " + i + ")");
  }
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  const callerLabels = ["one", "two"];
  const callerMessage: Broadcast = { channel: "news", labels: callerLabels };
  const seen: string[] = [];
  let firstObject: Broadcast | undefined;
  let secondObject: Broadcast | undefined;
  let completionCount = 0;

  broadcaster.subscribe((message, acknowledge) => {
    firstObject = message;
    seen.push("first");
    (message as { channel: string }).channel = "changed";
    (message.labels as string[]).push("private");
    acknowledge();
  });
  broadcaster.subscribe((message, acknowledge) => {
    secondObject = message;
    seen.push(message.channel);
    equalStrings(message.labels, ["one", "two"], "second listener labels must be isolated");
    acknowledge();
  });

  broadcaster.publish(callerMessage, (error) => {
    completionCount++;
    assert(error === null, "successful publication must report null");
  });

  assert(completionCount === 1, "publication must complete once");
  equalStrings(seen, ["first", "news"], "listeners must run in registration order");
  assert(firstObject !== undefined && secondObject !== undefined, "both listeners must receive messages");
  assert(firstObject !== secondObject, "each listener must receive its own object");
  assert(firstObject.labels !== secondObject.labels, "each listener must receive its own labels array");
  assert(callerMessage.channel === "news", "listener mutation must not change caller channel");
  equalStrings(callerLabels, ["one", "two"], "listener mutation must not change caller labels");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  const events: string[] = [];
  let unsubscribeSecond: () => void = () => undefined;

  broadcaster.subscribe((_message, acknowledge) => {
    events.push("first");
    unsubscribeSecond();
    broadcaster.subscribe((_laterMessage, laterAcknowledge) => {
      events.push("late");
      laterAcknowledge();
    });
    acknowledge();
  });
  unsubscribeSecond = broadcaster.subscribe((_message, acknowledge) => {
    events.push("second");
    acknowledge();
  });

  broadcaster.publish({ channel: "c", labels: [] }, (error) => {
    assert(error === null, "captured publication should succeed");
    events.push("complete");
  });

  equalStrings(events, ["first", "second", "complete"], "subscription changes must not affect active publication");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  let firstCount = 0;
  let secondCount = 0;
  const unsubscribeFirst = broadcaster.subscribe((_message, acknowledge) => {
    firstCount++;
    acknowledge();
  });
  const unsubscribeSecond = broadcaster.subscribe((_message, acknowledge) => {
    secondCount++;
    acknowledge();
  });

  unsubscribeFirst();
  unsubscribeFirst();
  broadcaster.publish({ channel: "c", labels: [] }, (error) => {
    assert(error === null, "remaining registration should succeed");
  });
  assert(firstCount === 0 && secondCount === 1, "unsubscribe must be independent and idempotent");

  unsubscribeSecond();
  let emptyCompleted = false;
  broadcaster.publish({ channel: "c", labels: [] }, (error) => {
    emptyCompleted = true;
    assert(error === null, "publication with no registrations must succeed");
  });
  assert(emptyCompleted, "publication with no registrations must complete immediately");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  const firstFailure = new Error("first failure");
  let firstAck: ((error?: Error) => void) | undefined;
  let secondAck: ((error?: Error) => void) | undefined;
  let completionCount = 0;
  let result: Error | null | undefined;

  broadcaster.subscribe((_message, acknowledge) => {
    firstAck = acknowledge;
  });
  broadcaster.subscribe((_message, acknowledge) => {
    secondAck = acknowledge;
  });
  broadcaster.subscribe(() => {
    throw "third failure";
  });

  broadcaster.publish({ channel: "errors", labels: [] }, (error) => {
    completionCount++;
    result = error;
  });

  assert(completionCount === 0, "publication must wait for every captured listener");
  assert(secondAck !== undefined, "second acknowledgement must be captured");
  secondAck();
  secondAck(new Error("ignored repeat"));
  assert(completionCount === 0, "publication must still wait for first listener");
  assert(firstAck !== undefined, "first acknowledgement must be captured");
  firstAck(firstFailure);
  assert(completionCount === 1, "publication must complete after all listeners settle");
  assert(result === firstFailure, "earliest registered failure must win");
  firstAck();
  assert(completionCount === 1, "repeated acknowledgement must not repeat completion");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  let result: Error | null | undefined;
  broadcaster.subscribe((_message, acknowledge) => {
    acknowledge();
    throw new Error("ignored after acknowledgement");
  });
  broadcaster.publish({ channel: "post-ack", labels: [] }, (error) => {
    result = error;
  });
  assert(result === null, "throw after acknowledgement must be ignored");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  let result: Error | null | undefined;
  broadcaster.subscribe(() => {
    throw 17;
  });
  broadcaster.publish({ channel: "throw", labels: [] }, (error) => {
    result = error;
  });
