{
  const links: ParentLink[] = [
    { id: "early-child", parentId: "branch-a" },
    { id: "root", parentId: null },
    { id: "branch-a", parentId: "root" },
    { id: "branch-b", parentId: "root" },
    { id: "late-child", parentId: "branch-a" },
    { id: "leaf-b", parentId: "branch-b" },
  ];
  const before = JSON.stringify(links);
  const report = inspectParentTree(links);

  assert(report.rootId === "root", "root ID");
  equalStrings(
    report.preorder,
    ["root", "branch-a", "early-child", "late-child", "branch-b", "leaf-b"],
    "preorder must preserve child input order",
  );
  assert(report.depthById["root"] === 0, "root depth");
  assert(report.depthById["branch-a"] === 1, "branch depth");
  assert(report.depthById["early-child"] === 2, "early child depth");
  assert(report.depthById["late-child"] === 2, "late child depth");
  assert(report.depthById["branch-b"] === 1, "second branch depth");
  assert(report.depthById["leaf-b"] === 2, "second leaf depth");
  equalStrings(report.pathById["root"], ["root"], "root path");
  equalStrings(report.pathById["early-child"], ["root", "branch-a", "early-child"], "early child path");
  equalStrings(report.pathById["late-child"], ["root", "branch-a", "late-child"], "late child path");
  equalStrings(report.pathById["leaf-b"], ["root", "branch-b", "leaf-b"], "second leaf path");
  assert(JSON.stringify(links) === before, "input links must not be mutated");
}

{
