Each node has a unique `id` and lists the IDs of its direct dependencies. The input is guaranteed to describe a valid directed acyclic graph, and every dependency ID refers to an input node.

`stableBuildOrder` must return every node ID exactly once, after all of its dependencies. Ordering must be stable: begin root traversals in input order, visit each node's dependencies in their listed order, and keep the placement established by the first traversal that reaches a shared dependency.

Do not use filesystem access, network access, clocks, randomness, or external packages.

Known-bad source:
```typescript
export interface PlanNode {
  readonly id: string;
  readonly dependencies: readonly string[];
}

export function stableBuildOrder(nodes: readonly PlanNode[]): string[] {
  const byId = new Map(nodes.map((node) => [node.id, node]));
  const visited = new Set<string>();
  const result: string[] = [];

  const visit = (id: string): void => {
    if (visited.has(id)) {
      return;
    }

    const node = byId.get(id)!;
    for (const dependency of node.dependencies.slice().reverse()) {
      visit(dependency);
    }

    visited.add(id);
    result.push(id);
  };

  for (const node of nodes) {
    visit(node.id);
  }

  return result;
}
