{"items":[{"id":"cap-v2-graph_and_tree-typescript-repair-02","test_code":"import { stableBuildOrder } from './solution';

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, received ${String(actual)}`);
  }
}

function assertArrayEqual(actual: readonly string[], expected: readonly string[], message: string): void {
  assertEqual(actual.length, expected.length, `${message} (length)`);
  for (let i = 0; i < expected.length; i += 1) {
    assertEqual(actual[i], expected[i], `${message} (index ${i})`);
  }
}

assertArrayEqual(stableBuildOrder([]), [], 'empty graph');

const chain = [
  { id: 'package', dependencies: ['compile'] },
  { id: 'compile', dependencies: ['generate'] },
  { id: 'generate', dependencies: [] },
] as const;
assertArrayEqual(stableBuildOrder(chain), ['generate', 'compile', 'package'], 'dependency chain');

const orderedDependencies = [
  { id: 'app', dependencies: ['config', 'library', 'assets'] },
  { id: 'assets', dependencies: [] },
  { id: 'library', dependencies: [] },
  { id: 'config', dependencies: [] },
] as const;
assertArrayEqual(
  stableBuildOrder(orderedDependencies),
  ['config', 'library', 'assets', 'app'],
  'dependencies retain their listed traversal order',
);

const sharedDependency = [
  { id: 'root-a', dependencies: ['a-only', 'shared'] },
  { id: 'root-b', dependencies: ['b-only', 'shared'] },
  { id: 'shared', dependencies: ['base'] },
  { id: 'b-only', dependencies: [] },
  { id: 'a-only', dependencies: [] },
  { id: 'base', dependencies: [] },
] as const;
assertArrayEqual(
  stableBuildOrder(sharedDependency),
  ['a-only', 'base', 'shared', 'root-a', 'b-only', 'root-b'],
  'first root traversal establishes shared dependency placement',
);

const independentRoots = [
  { id: 'second-root', dependencies: [] },
  { id: 'first-root', dependencies: [] },
] as const;
assertArrayEqual(
  stableBuildOrder(independentRoots),
  ['second-root', 'first-root'],
  'independent roots follow input order',
);

const mutableInput = [
  { id: 'x', dependencies: ['z', 'y'] as string[] },
  { id: 'y', dependencies: [] as string[] },
  { id: 'z', dependencies: [] as string[] },
];
const nodeOrderBefore = mutableInput.map((node) => node.id).join('|');
const dependenciesBefore = mutableInput.map((node) => node.dependencies.join('|')).join(';');
const firstResult = stableBuildOrder(mutableInput);
assertArrayEqual(firstResult, ['z', 'y', 'x'], 'mutable input result');
assertEqual(mutableInput.map((node) => node.id).join('|'), nodeOrderBefore, 'node order is not mutated');
assertEqual(
  mutableInput.map((node) => node.dependencies.join('|')).join(';'),
  dependenciesBefore,
  'dependency arrays are not mutated',
);

firstResult.push('injected');
assertArrayEqual(stableBuildOrder(mutableInput), ['z', 'y', 'x'], 'results do not leak across calls');"},{"id":"cap-v2-numeric_reasoning-typescript-generation-01","test_code":"import { createUsageMeter } from './solution';

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, received ${String(actual)}`);
  }
}

function assertRangeError(action: () => unknown, message: string): void {
  let thrown: unknown;
  try {
    action();
  } catch (error) {
    thrown = error;
  }
  if (!(thrown instanceof RangeError)) {
    throw new Error(`${message}: expected RangeError`);
  }
}

for (const invalidLimit of [0, -1, 1.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY, Number.MAX_SAFE_INTEGER + 1]) {
  assertRangeError(() => createUsageMeter(invalidLimit), `invalid limit ${String(invalidLimit)}`);
}

const meter = createUsageMeter(10);
assertEqual(meter.used(), 0, 'new meter starts unused');
assertEqual(meter.remaining(), 10, 'new meter has full capacity');
assertEqual(meter.utilization(), 0, 'new meter has zero utilization');
assertEqual(meter.consume(4), 4, 'consume returns accepted units');
assertEqual(meter.used(), 4, 'consume increases usage');
assertEqual(meter.remaining(), 6, 'remaining decreases after consume');
assertEqual(meter.utilization(), 0.4, 'utilization reflects usage');
assertEqual(meter.consume(9), 6, 'consume is capped by remaining capacity');
assertEqual(meter.used(), 10, 'usage reaches limit');
assertEqual(meter.consume(1), 0, 'full meter accepts nothing');
assertEqual(meter.release(3), 3, 'release returns removed units');
assertEqual(meter.used(), 7, 'release decreases usage');
assertEqual(meter.release(20), 7, 'release is capped by current usage');
assertEqual(meter.used(), 0, 'release can empty meter');
assertEqual(meter.release(1), 0, 'empty meter releases nothing');
assertEqual(meter.consume(0), 0, 'zero consume is accepted');
assertEqual(meter.release(0), 0, 'zero release is accepted');

meter.consume(5);
for (const invalidUnits of [-1, 0.25, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY, Number.MAX_SAFE_INTEGER + 1]) {
  assertRangeError(() => meter.consume(invalidUnits), `consume rejects ${String(invalidUnits)}`);
  assertEqual(meter.used(), 5, 'failed consume preserves state');
  assertRangeError(() => meter.release(invalidUnits), `release rejects ${String(invalidUnits)}`);
  assertEqual(meter.used(), 5, 'failed release preserves state');
}

const first = createUsageMeter(3);
const second = createUsageMeter(3);
assertEqual(first.consume(3), 3, 'first independent meter consumes');
assertEqual(second.used(), 0, 'second meter is unaffected');
assertEqual(second.consume(2), 2, 'second independent meter consumes');
assertEqual(first.remaining(), 0, 'first meter remains full');
assertEqual(second.remaining(), 1, 'second meter has independent capacity');

const maximum = createUsageMeter(Number.MAX_SAFE_INTEGER);
assertEqual(maximum.consume(Number.MAX_SAFE_INTEGER), Number.MAX_SAFE_INTEGER, 'safe-integer boundary consume');
assertEqual(maximum.remaining(), 0, 'safe-integer boundary remaining');
assertEqual(maximum.utilization(), 1, 'safe-integer boundary utilization');
assertEqual(maximum.release(Number.MAX_SAFE_INTEGER), Number.MAX_SAFE_INTEGER, 'safe-integer boundary release');"},{"id":"cap-v2-numeric_reasoning-typescript-generation-02","test_code":"import { createRollingAverage } from './solution';

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, received ${String(actual)}`);
  }
}

function assertClose(actual: number, expected: number, message: string): void {
  const tolerance = Number.EPSILON * Math.max(1, Math.abs(actual), Math.abs(expected)) * 8;
  if (Math.abs(actual - expected) > tolerance) {
    throw new Error(`${message}: expected ${expected}, received ${actual}`);
  }
}

function assertRangeError(action: () => unknown, message: string): void {
  let thrown: unknown;
  try {
    action();
  } catch (error) {
    thrown = error;
  }
  if (!(thrown instanceof RangeError)) {
    throw new Error(`${message}: expected RangeError`);
  }
}

for (const invalidWidth of [0, -1, 1.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  assertRangeError(() => createRollingAverage(invalidWidth), `invalid width ${String(invalidWidth)}`);
}

const average = createRollingAverage(3);
assertEqual(average.mean(), undefined, 'mean is undefined before the first push');
assertEqual(average.count(), 0, 'new window is empty');
assertEqual(average.push(2), 2, 'first push mean');
assertEqual(average.count(), 1, 'count after first push');
assertEqual(average.push(4), 3, 'second push mean');
assertEqual(average.push(9), 5, 'full-window mean');
assertEqual(average.count(), 3, 'count is capped at width');
assertClose(average.push(15), 28 / 3, 'oldest sample is evicted');
assertEqual(average.count(), 3, 'count remains capped after eviction');
assertClose(average.mean() as number, 28 / 3, 'mean matches the latest push result');
assertClose(average.push(-3), 7, 'negative finite values are accepted');

const fractional = createRollingAverage(2);
assertClose(fractional.push(0.1), 0.1, 'fractional first value');
assertClose(fractional.push(0.2), 0.15, 'fractional mean');
assertClose(fractional.push(0.3), 0.25, 'fractional eviction mean');

const single = createRollingAverage(1);
assertEqual(single.push(-0), -0, 'negative zero is finite');
assertEqual(single.count(), 1, 'width-one count');
assertEqual(single.push(8), 8, 'width one retains only newest value');
assertEqual(single.mean(), 8, 'width-one mean');

const stable = createRollingAverage(2);
stable.push(10);
for (const invalidValue of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  assertRangeError(() => stable.push(invalidValue), `push rejects ${String(invalidValue)}`);
  assertEqual(stable.count(), 1, 'failed push preserves count');
  assertEqual(stable.mean(), 10, 'failed push preserves mean');
}

const first = createRollingAverage(2);
const second = createRollingAverage(2);
first.push(1);
first.push(3);
first.push(5);
assertEqual(second.count(), 0, 'second instance is unaffected by first');
assertEqual(second.mean(), undefined, 'second instance remains empty');
assertEqual(second.push(20), 20, 'second instance accepts its own sample');
assertEqual(first.mean(), 4, 'first instance retains its own window');

const veryWide = createRollingAverage(Number.MAX_SAFE_INTEGER);
assertEqual(veryWide.push(6), 6, 'large positive integer width is supported');
assertEqual(veryWide.count(), 1, 'large-width window count');"},{"id":"cap-v2-numeric_reasoning-typescript-repair-01","test_code":"import { totalUniqueCharge } from './solution';

